INSERT INTO `recipes` (`recipe_id`, `title`, `description`, `instructions`, `prep_time`, `cook_time`, `servings`, `difficulty`, `image_url`, `status`, `created_at`, `updated_at`, `created_by`, `is_duplicate_suspected`) VALUES
(1, 'Vegetarian Pasta', 'Vegetarian Pasta is an Asian-style dish prepared with selected ingredients. It is a simple and flavorful recipe suitable for everyday meals.', 'Boil pasta. Cook vegetables. Mix with sauce.', 10, 10, 2, 'medium', '/images/recipes/0ee33dc7-a14e-4a15-bd62-e4d972682a78.png', 'approved', '2026-03-05 08:46:56', '2026-04-05 00:27:07', 1, 0),
(2, 'Chicken Fried Rice', 'Chicken Fried Rice is an Asian-style dish prepared with selected ingredients. It is a simple and flavorful recipe suitable for everyday meals.', 'Cook rice. Stir fry chicken and vegetables. Combine.', 10, 15, 3, 'medium', '/images/recipes/04de18b7-d8ef-4323-bff4-360f704ac563.webp', 'approved', '2026-03-05 08:46:56', '2026-04-05 00:26:11', 1, 0),
(3, 'Vegan Salad Bowl', 'Vegan Salad Bowl is an Asian-style dish prepared with selected ingredients. It is a simple and flavorful recipe suitable for everyday meals.', 'Chop vegetables. Mix with olive oil and lemon dressing.', 10, 10, 1, 'medium', '/images/recipes/99b4f9ca-df50-4b11-9358-8ebafd8dd6c0.png', 'approved', '2026-03-05 08:46:56', '2026-04-07 21:07:40', 1, 0),
(4, 'braised pork', 'braised pork is an Asian-style dish prepared with bok choy, egg, pork. It is a simple and flavorful recipe suitable for everyday meals.', 'Prepare all ingredients needed for braised pork. Wash, cut, and measure them properly. Heat a pan or pot and sauté aromatics until fragrant. Add bok choy, egg, pork and cook until they are evenly mixed and partially cooked. Season to taste and continue cooking until the dish is fully done. Serve braised pork hot and enjoy.', 10, 30, 2, 'medium', '/images/recipes/966c38b4-1879-4c22-ab73-3761c9318157.jpg', 'approved', '2026-03-05 08:49:21', '2026-04-04 22:28:54', 2, 0),
(5, 'cabbage and tofu coup', 'cabbage and tofu coup is an Asian-style dish prepared with cabbage, scallion, tofu. It is a simple and flavorful recipe suitable for everyday meals.', 'Prepare all ingredients needed for cabbage and tofu coup. Wash, cut, and measure them properly. Heat a pan or pot and sauté aromatics until fragrant. Add cabbage, scallion, tofu and cook until they are evenly mixed and partially cooked. Season to taste and continue cooking until the dish is fully done. Serve cabbage and tofu coup hot and enjoy.', 10, 10, 2, 'medium', '/images/recipes/6415dbd8-3e61-4025-b4be-d165e6f463f4.jpg', 'approved', '2026-03-05 08:49:21', '2026-04-04 22:32:56', 2, 0),
(6, 'fried egg', 'fried egg is an Asian-style dish prepared with carrot, egg, green bean. It is a simple and flavorful recipe suitable for everyday meals.', 'Prepare all ingredients needed for fried egg. Wash, cut, and measure them properly. Heat a pan or pot and sauté aromatics until fragrant. Add carrot, egg, green bean and cook until they are evenly mixed and partially cooked. Season to taste and continue cooking until the dish is fully done. Serve fried egg hot and enjoy.', 10, 15, 2, 'medium', '/images/recipes/73c509c0-0814-4bde-a94b-c770183b5f6e.jpg', 'approved', '2026-03-05 08:49:21', '2026-04-04 22:34:48', 2, 0),
(7, 'fried egg deluxe version', 'fried egg deluxe version is an Asian-style dish prepared with carrot, corn, egg. It is a simple and flavorful recipe suitable for everyday meals.', 'Prepare all ingredients needed for fried egg deluxe version. Wash, cut, and measure them properly. Heat a pan or pot and sauté aromatics until fragrant. Add carrot, corn, egg and cook until they are evenly mixed and partially cooked. Season to taste and continue cooking until the dish is fully done. Serve fried egg deluxe version hot and enjoy.', 15, 15, 2, 'medium', '/images/recipes/5b2fb83e-1cbd-47a3-a638-6a3f820acd99.jpg', 'approved', '2026-03-05 08:49:21', '2026-04-04 22:36:20', 2, 0),
