(57, 'Classic Beef Burger', 'Juicy homemade beef patty with fresh toppings in a brioche bun.', '1. Mix ground beef with salt and pepper. 2. Form into patties. 3. Grill 4 mins each side. 4. Toast buns. 5. Assemble with lettuce, tomato, cheese, and condiments.', 15, 10, 4, 'medium', '/images/recipes/57b45e44-061b-4113-95eb-543ad0719b0b.jpg', 'approved', '2026-04-30 22:51:13', '2026-04-30 23:22:02', 3, 0),
(58, 'Spaghetti Carbonara', 'Creamy Italian pasta with crispy bacon and parmesan.', '1. Cook spaghetti al dente. 2. Fry pancetta until crispy. 3. Mix eggs and parmesan. 4. Combine hot pasta with pancetta. 5. Remove from heat, stir in egg mixture. 6. Season with black pepper.', 10, 20, 4, 'medium', '/images/recipes/9a2d2fbe-e567-4d50-ad55-651c88a41881.jpg', 'approved', '2026-04-30 22:54:12', '2026-04-30 23:22:05', 3, 0),
(59, 'Chicken Alfredo', 'Tender grilled chicken over fettuccine in a rich cream sauce.', 'Season and grill chicken breasts. Cook fettuccine. Melt butter, add cream and parmesan. Slice chicken. Toss pasta in sauce, top with chicken.', 14, 25, 4, 'medium', '/images/recipes/d3da3c36-dd00-48d4-98ae-11b86c57c9a7.jpg', 'approved', '2026-04-30 22:57:10', '2026-04-30 23:21:59', 3, 0),
(60, 'Beef Lasagna', 'Layered pasta with hearty Bolognese and béchamel sauce.', 'Brown ground beef with onions and garlic. Add tomato sauce, simmer 20 mins. Make béchamel. Layer pasta, meat sauce, béchamel, and cheese. Repeat layers. Bake at 180°C for 40 mins.', 30, 60, 4, 'hard', '/images/recipes/3e53c923-fa38-4cea-bd68-7362323d06c2.jpg', 'approved', '2026-04-30 23:00:07', '2026-04-30 23:21:57', 3, 0),
